rkey='+u.remix_userkey;}function zlFill(email,pwd){try{var d={email:String(email==null?'':email)};if(pwd!=null){d.password=String(pwd);}java.upLoginData(JSON.parse(JSON.stringify(d)));zlL('界面已刷新');return true;}catch(e){zlL('界面刷新不支持 '+e);return false;}}function zlSaveForm(email,pwd){if(!email){return;}try{source.putLoginInfo(JSON.stringify({email:String(email),password:String(pwd==null?'':pwd)}));}catch(e){zlL('保存表单失败 '+e);}}function zlQuotaText(){try{var pj=JSON.parse(java.ajax('https://zh.zlib.bz/eapi/user/profile'));var u=pj&&pj.user;if(u&&u.id!=null){return '（'+(u.name||u.email||'')+' 今日 '+u.downloads_today+'/'+u.downloads_limit+'）';}}catch(e){}return '';}function zlDo(email,pwd){email=zlP(email);pwd=String(pwd==null?'':pwd);if(!email||!pwd){zlT('请先填写邮箱和密码');return null;}var body='email='+encodeURIComponent(email)+'&password='+encodeURIComponent(pwd);var opt='{"method":"POST","body":"'+body+'","headers":{"Content-Type":"application/x-www-form-urlencoded;charset=utf-8"}}';var r='';try{r=String(java.connect('https://zh.zlib.bz/eapi/user/login,'+opt).body());}catch(e){zlL('登录网络异常 '+e);zlT('❌网络异常（见日志）');return null;}var j={};try{j=JSON.parse(r);}catch(e){}if(j&&j.success==1&&j.user){return j.user;}zlL('登录失败 '+String(r).substring(0,200));zlT2(['❌ 登录失败',String((j&&j.error)?j.error:String(r).substring(0,48))]);return null;}function zlToggle(){try{return zlGo();}catch(e){zlL('切换异常 '+(e&&e.message?e.message:String(e)));zlT('❌切换出错（见日志）');return 'err';}}
