function login(){
var st=zlSt();
var email=zlP(zlG('email')),pwd=zlP(zlG('password'));
if(st.alte&&email===st.alte){
zlPut(st.alt,st.alte,st.cur,st.cure);
zlSaveForm(email,'');
zlFill(email,'********');
zlT2(['🔁 已切换',email]);
return 'ok';
}
if(st.cure&&email===st.cure){zlSaveForm(email,'');return 'keep';}
if(email&&pwd){
