try{
var u=null;
try{var pj=JSON.parse(java.ajax('https://zh.zlib.bz/eapi/user/profile'));u=(pj&&pj.user)||null;if(!u||!u.id){rep.push('profile: '+String(pj).substring(0,120));}}catch(e){rep.push('profile 异常: '+e);}
