}else{rep.push('跳过详情/评论（搜索无结果）');}
rep.push('搜索'+(sOK?'OK':'FAIL')+' 详情'+(dOK?'OK':'FAIL')+' 评论'+(cOK?'OK':'FAIL'));
if(!loginOK||!sOK||!dOK||!cOK){bad=true;}
try{var lg=JSON.parse(String(cache.get('zl_log')||'')||'[]')||[];
if(lg&&lg.length){
var dt=[];for(var qi=lg.length-1;qi>=0;qi--){var x=lg[qi]||{};var dd=new Date(x.t||Date.now());
dt.push(('0'+dd.getHours()).slice(-2)+':'+('0'+dd.getMinutes()).slice(-2)+' 打开#'+(x.b||'?')+' 账号'+(x.a||'?')+' 已用'+(x.cur==null?'?':x.cur)+' 上次'+(x.prev==null?'-':x.prev)+' 归属'+(x.to||'-')+(x.hit?' → 判定下载':''));}
rep.push('下载检测('+lg.length+'):\n'+dt.join('\n'));
}else{rep.push('下载检测: 暂无记录');}}catch(e){}
