   var js="(function(){try{var m=String(document.cookie).match(/c_token=([^;]+)/);if(m){return m[1];}var C=null,S=null;try{if(typeof c!=='undefined'){C=c;}}catch(e){}try{if(typeof s1!=='undefined'){S=s1;}}catch(e){}if(!C){var mm=String(document.documentElement.innerHTML).match(/[0-9A-Fa-f]{40}/);if(mm){C=mm[0];}}if(!C||!S){return '';}var n1=parseInt(C.charAt(0),16);for(var i=0;i<4000000;i++){var s=S.array(C+i);if(s[n1]===0xb0&&s[n1+1]===0x0b){document.cookie='c_token='+C+i+'; path=/';document.cookie='c_time=0.4; path=/';return String(C)+String(i);}}return '';}catch(e){return '';}})()";
   try{tok=String(java.webView(null,page,js)||'');}catch(e){}
